import * as THREE from 'three';
const visible=o=>{for(let n=o;n;n=n.parent)if(!n.visible)return false;return true;};
export class CabinetInteraction135{
 constructor(view){this.view=view;this.rows=[];this.hovered=null;this.lastHover=0;const counts={};
  for(const door of view.model.userData.doors){let part=door.parent;while(part&&!part.userData.partId)part=part.parent;const id=part?.userData.partId;if(!id)continue;counts[id]=(counts[id]||0)+1;this.rows.push({door,id,label:(door.userData.cover177?'Banco de baterías':({mt:'Celda MT',dc:'Distribución CD',control:'Control / RTU',rectifier:'Rectificador',transformer:'Resguardo transformador',aux:'Servicios auxiliares',battery:'Cargador auxiliar'})[id])+' '+counts[id],open:false,amount:0,closed:new THREE.Quaternion(),opened:door.quaternion.clone().normalize()});door.quaternion.identity();}
  this.rows.sort((a,b)=>a.door.position.x-b.door.position.x);this.helper=new THREE.Box3Helper(new THREE.Box3(),0xeac773);this.helper.visible=false;view.scene.add(this.helper);
  const doc=view.dialog.ownerDocument||document,stage=view.canvas.parentElement;this.tip=doc.createElement('output');this.tip.className='sr135-hover';this.tip.hidden=true;stage.append(this.tip);
  const panel=view.dialog.querySelector('[data-sr-cabinets]');if(panel){panel.innerHTML='<h3>Gabinetes interactivos</h3><p>Abre una puerta para inspeccionar sus componentes. Vuelve a pulsar para cerrarla.</p><div data-sr135-cabinet-list></div>';for(const row of this.rows){const b=doc.createElement('button');b.type='button';b.addEventListener('click',()=>{view.select(row.id,true);this.toggle(row);});panel.querySelector('[data-sr135-cabinet-list]').append(b);row.button=b;}}
  view.canvas.addEventListener('pointermove',e=>{if(view.service128?.active||view.down){this.clearHover();return;}if(performance.now()-this.lastHover<45)return;this.lastHover=performance.now();const hit=this.pick(e);this.hovered=hit;this.tip.hidden=!hit;if(hit){this.tip.textContent=hit.label+' · '+(hit.open?'Cerrar':'Abrir')+' con clic';const r=stage.getBoundingClientRect();this.tip.style.left=Math.max(8,Math.min(r.width-220,e.clientX-r.left+16))+'px';this.tip.style.top=Math.max(8,Math.min(r.height-48,e.clientY-r.top+16))+'px';this.helper.box.setFromObject(hit.door);this.helper.visible=true;}else this.helper.visible=false;view.canvas.style.cursor=hit?'pointer':'';});view.canvas.addEventListener('pointerleave',()=>this.clearHover());view.canvas.addEventListener('pointerdown',()=>this.clearHover());view.canvas.addEventListener('wheel',()=>this.clearHover());this.render();
 }
 pick(e){if(this.view.service128?.active||this.view.navigation.mode==='pan')return null;const v=this.view,r=v.canvas.getBoundingClientRect();v.model.updateMatrixWorld(true);v.camera.updateMatrixWorld(true);v.pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);v.ray.setFromCamera(v.pointer,v.camera);const hit=v.ray.intersectObject(v.model,true).find(h=>visible(h.object)&&!(h.object.material?.transparent&&h.object.material.opacity<.2));if(!hit)return null;return this.rows.find(row=>{for(let n=hit.object;n;n=n.parent)if(n===row.door)return true;return false;})||null;}
 activate(e){const row=this.pick(e);if(!row)return false;this.view.select(row.id,false);this.toggle(row);return true;}
 toggle(row){if(this.view.service128?.active)return;row.open=!row.open;this.render();this.view.status.textContent=row.label+' · '+(row.open?'abriendo: interior disponible para inspección.':'cerrando gabinete.');}
 setAll(open){if(this.view.service128?.active)return;for(const row of this.rows)row.open=open;this.clearHover();this.render();this.view.status.textContent=open?'Abriendo '+this.rows.length+' puertas. Pulsa una hoja para cerrarla individualmente.':'Cerrando '+this.rows.length+' puertas.';}
 render(){for(const row of this.rows)if(row.button){row.button.textContent=(row.open?'Cerrar · ':'Abrir · ')+row.label;row.button.setAttribute('aria-pressed',String(row.open));}const all=this.rows.every(r=>r.open),button=this.view.dialog.querySelector('[data-sr-doors]');button.textContent=all?'Cerrar gabinetes':'Abrir gabinetes';button.setAttribute('aria-pressed',String(all));}
 update(dt){if(this.view.service128?.active){this.clearHover();return;}let moving=false;for(const row of this.rows){const target=row.open?1:0,d=target-row.amount;if(Math.abs(d)<.001){row.amount=target;}else{row.amount+=Math.sign(d)*Math.min(Math.abs(d),Math.max(0,Math.min(dt,.05))/0.85);moving=true;}const t=row.amount*row.amount*(3-2*row.amount);row.door.quaternion.slerpQuaternions(row.closed,row.opened,t);}if(moving&&this.view.renderer?.shadowMap)this.view.renderer.shadowMap.needsUpdate=true;if(this.hovered&&visible(this.hovered.door))this.helper.box.setFromObject(this.hovered.door);}
 clearHover(){this.hovered=null;this.helper.visible=false;this.tip.hidden=true;if(!this.view.service128?.active)this.view.canvas.style.cursor='';}
}
